  "7b696878-bf6c-4323-baa5-93c44dde075e": { id: "7b696878-bf6c-4323-baa5-93c44dde075e", name: "Chimil, the Inner Sun", set: "ecc", setName: "Lorwyn Eclipsed Commander", rarity: "mythic", manaCost: "{6}", cmc: 6, typeLine: "Legendary Artifact", oracleText: "Spells you control can't be countered.\nAt the beginning of your end step, discover 5. (Exile cards from the top of your library until you exile a nonland card with mana value 5 or less. Cast it without paying its mana cost or put it into your hand. Put the rest on the bottom in a random order.)", colors: [], image: { small: "https://cards.scryfall.io/small/front/7/b/7b696878-bf6c-4323-baa5-93c44dde075e.jpg?1783904531", normal: "https://cards.scryfall.io/normal/front/7/b/7b696878-bf6c-4323-baa5-93c44dde075e.jpg?1783904531", large: "https://cards.scryfall.io/large/front/7/b/7b696878-bf6c-4323-baa5-93c44dde075e.jpg?1783904531" }, scryfallUri: "https://scryfall.com/card/ecc/137/chimil-the-inner-sun" },
  "d3ca43a4-d194-440f-8099-f1fa103a108d": { id: "d3ca43a4-d194-440f-8099-f1fa103a108d", name: "Aven Interrupter", set: "otj", setName: "Outlaws of Thunder Junction", rarity: "rare", manaCost: "{1}{W}{W}", cmc: 3, typeLine: "Creature — Bird Rogue", oracleText: "Flash\nFlying\nWhen this creature enters, exile target spell. It becomes plotted. (Its owner may cast it as a sorcery on a later turn without paying its mana cost.)\nSpells your opponents cast from graveyards or from exile cost {2} more to cast.", colors: ["W"], image: { small: "https://cards.scryfall.io/small/front/d/3/d3ca43a4-d194-440f-8099-f1fa103a108d.jpg?1783911861", normal: "https://cards.scryfall.io/normal/front/d/3/d3ca43a4-d194-440f-8099-f1fa103a108d.jpg?1783911861", large: "https://cards.scryfall.io/large/front/d/3/d3ca43a4-d194-440f-8099-f1fa103a108d.jpg?1783911861" }, scryfallUri: "https://scryfall.com/card/otj/4/aven-interrupter" },
  "dc2c1de0-6233-469a-be72-a050b97d2c8f": { id: "dc2c1de0-6233-469a-be72-a050b97d2c8f", name: "Coruscation Mage", set: "blb", setName: "Bloomburrow", rarity: "uncommon", manaCost: "{1}{R}", cmc: 2, typeLine: "Creature — Otter Wizard", oracleText: "Offspring {2} (You may pay an additional {2} as you cast this spell. If you do, when this creature enters, create a 1/1 token copy of it.)\nWhenever you cast a noncreature spell, this creature deals 1 damage to each opponent.", colors: ["R"], image: { small: "https://cards.scryfall.io/small/front/d/c/dc2c1de0-6233-469a-be72-a050b97d2c8f.jpg?1783910824", normal: "https://cards.scryfall.io/normal/front/d/c/dc2c1de0-6233-469a-be72-a050b97d2c8f.jpg?1783910824", large: "https://cards.scryfall.io/large/front/d/c/dc2c1de0-6233-469a-be72-a050b97d2c8f.jpg?1783910824" }, scryfallUri: "https://scryfall.com/card/blb/131/coruscation-mage" },
